input.content:
@font-face {
  font-family: "Inter";
  font-weight: 400;
  src: url("fonts/inter-latin-400-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Inter";
  font-weight: 500;
  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

/* Side margin: at least 64px, and wider on big screens so the content never grows past 1152px. */
:root {
  --page-margin: max(64px, calc((100% - 1152px) / 2));
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 16px;
  line-height: 1.55;
  color: #2a2622;
  background: #fffdf9;
}

a {
  color: inherit;
}

.site-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 18px var(--page-margin);
  border-bottom: 1px solid #ece6dc;
}

.logo {
  font-size: 20px;
  font-weight: 500;
  text-decoration: none;
}

.site-nav {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 28px;
}

.site-nav a {
  text-decoration: none;
  white-space: nowrap;
  color: #5c544b;
}

.site-nav .nav-signin {
  color: #2a2622;
  font-weight: 500;
}

.hero {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 64px;
  padding: 64px var(--page-margin) 48px;
}

.hero-text {
  max-width: 540px;
}

h1 {
  margin: 0 0 16px;
  font-size: 40px;
  font-weight: 500;
  line-height: 1.15;
  /* Spread the words evenly over the lines, so no line holds one word alone. */
  text-wrap: balance;
}

.hero-text p {
  margin: 0 0 28px;
  color: #5c544b;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.button {
  display: inline-block;
  padding: 10px 18px;
  border-radius: 6px;
  text-decoration: none;
  white-space: nowrap;
}

.button-primary {
  border: 1px solid #8a3b24;
  background: #8a3b24;
  color: #ffffff;
  font-weight: 500;
}

.button-secondary {
  border: 1px solid #8f8477;
  background: #fffdf9;
  color: #2a2622;
}

.preview {
  flex: 0 0 480px;
  border: 1px solid #ece6dc;
  border-radius: 8px;
  background: #ffffff;
}

.preview-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 14px 18px;
  border-bottom: 1px solid #ece6dc;
  font-weight: 500;
}

.preview-date {
  color: #6f665d;
  font-weight: 400;
  font-size: 14px;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

th,
td {
  padding: 9px 18px;
  text-align: left;
  border-bottom: 1px solid #f3eee6;
}

/* Right-align the two number columns so the digits line up. */
th:not(:first-child),
td:not(:first-child) {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

th {
  color: #6f665d;
  font-weight: 400;
}

tbody tr:last-child td {
  border-bottom: none;
}

.facts {
  display: flex;
  gap: 40px;
  padding: 8px var(--page-margin) 64px;
}

.facts p {
  flex: 1;
  margin: 0;
  color: #5c544b;
}

.fact-title {
  color: #2a2622;
  font-weight: 500;
}

/* Tablet and phone: one column, so nothing runs past the screen edge. */
@media (max-width: 960px) {
  :root {
    --page-margin: 32px;
  }

  .hero {
    flex-direction: column;
    align-items: stretch;
    gap: 40px;
    padding-top: 48px;
  }

  .preview {
    flex: none;
  }

  .facts {
    flex-direction: column;
    gap: 20px;
  }

  .facts p {
    max-width: 600px;
  }
}

/* Phone: put the nav on its own line under the logo. */
@media (max-width: 600px) {
  :root {
    --page-margin: 20px;
  }

  .site-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
  }

  .site-nav {
    gap: 8px 20px;
  }

  h1 {
    font-size: 32px;
  }

  th,
  td {
    padding: 9px 12px;
  }
}

