@media (max-width: 960px) {
  :root {
    --page-margin: 32px;
  }

  .hero {
    flex-direction: column;
    align-items: stretch;
    gap: 40px;
    padding-top: 48px;
  }

  /* Hero text, table, and facts share one width, so they end at one right edge. */
  .preview {
    flex: none;
    max-width: 540px;
  }

  .facts {
    grid-template-columns: 1fr;
    gap: 20px;
  }

  .facts p {
    max-width: 540px;
  }
}

/* Phone: put the nav on its own line under the logo. */
@media (max-width: 600px) {
  :root {
    --page-margin: 20px;
  }

  .site-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
  }

  .site-nav {
    gap: 8px 20px;
  }

  h1 {
    font-size: 32px;
  }

  /* Tighter cells, so each header and title fits on one line. */
  .preview-head {
    padding: 14px 12px;
  }

  th,
  td {
    padding: 9px 8px;
    white-space: nowrap;
  }

  th:first-child,
  td:first-child {
    padding-left: 12px;
  }

  th:last-child,
  td:last-child {
    padding-right: 12px;
  }
}

